// Тикет #c66fac12 (c66fac122c16a223a577751a) «ממשק הניהול מקבל קובץ MP3 פגום…» — ИСПРАВЛЕН, עבר QA 13.10.2026 (iPhone, TestFlight 1.0.0 (19)).
// История: 07.10 битый файл получал «ממתינה לאישור» (upfail-4-*); 11.10 тест ждал загрузку MP3 в приложении (F-92).
// Факт 13.10 (скрин c66fac12-ios-b19-broken-mp3-rejected.png), загрузка в приложении, аккаунт клиента:
//  профиль → «ממשק ניהול התוכן» → «בורא פרי העץ · נוסח אשכנז…» → «1, בורא פרי העץ…» → «מי הקליט» → «העלאת קובץ MP3» → файл qa-broken.mp3 →
//  «הקובץ שנבחר אינו קובץ שמע תקין, ולכן לא נטען. העלו קובץ MP3 אחר.»; записи нет («לקטע הזה אין עדיין הקראה…»), нет «ממתינה לאישור»/«אושרה».
// Опора: решение пользователя 07.10 — «если MP3 не загрузился у админа — должна быть ошибка и не должно быть статуса אושרה»; F-92 AC2.
// Файл: .qa/research/rec-pages/qa-broken.mp3. Android — кладётся автоматически; iOS — должен лежать в «Файлы» на телефоне,
// выбор в системном пикере — @manual-check, если автоматический тап не нашёл файл (тест ждёт до 3 минут).
// Ничего не сохраняется (@prod-safe); страховка в finally — если запись всё же приняли (регресс), «הסרת ההקראה».
import fs from 'node:fs';
import { driver, expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { shown, skipWith } from '../_lib/app-0710.ts';
import {
  asAdmin, backToUser1, qaFile, pushToDownloads, removeFromDevice,
  REC_CARD, REC_NONE, REC_PENDING, REC_APPROVE_BTN, REC_APPROVED_RE,
} from '../_lib/admin.ts';
import { openAdminHaetzSection, uploadRecordingAny, removeRecordingWithDialog, REC_BROKEN, REC_NONE_PREFIX } from '../_lib/app-1310.ts';

const FILE = 'qa-broken.mp3';

describe('Админка в приложении: битый MP3', () => {
  afterEach(async () => { await toHome(); });

  it('AD-08 битый qa-broken.mp3 → «הקובץ שנבחר אינו קובץ שמע תקין…», записи нет #c66fac12 @prod-safe @manual-check', async function () {
    let remote = '';
    await asAdmin();
    try {
      if (driver.isAndroid) remote = await pushToDownloads(FILE, fs.readFileSync(qaFile(`research/rec-pages/${FILE}`)).toString('base64'));
      await openAdminHaetzSection();
      await scrollToText(REC_CARD);
      if (!(await shown(byTextContains(REC_NONE)))) skipWith(this, 'у «בורא פרי העץ» אשכנז уже есть запись — проверка «записи нет» невозможна');

      // 1. «מי הקליט» → «העלאת קובץ MP3» → битый файл.
      await uploadRecordingAny(FILE, 'QA test');

      // 2. Ошибка с точным текстом; запись не принята.
      await expect(byTextContains(REC_BROKEN)).toBeDisplayed({ wait: 180000 });
      await expect(byTextContains(REC_PENDING)).not.toBeDisplayed();
      await expect(byText(REC_APPROVE_BTN)).not.toBeDisplayed();
      await expect(byTextMatches(REC_APPROVED_RE)).not.toBeDisplayed();
      await expect(await scrollToText(REC_NONE_PREFIX)).toBeDisplayed();
    } finally {
      try {
        if (remote) await removeFromDevice(remote);
        if (await shown(byTextContains(REC_PENDING))) await removeRecordingWithDialog();
      } catch (e) {
        console.warn('[AD-08] страховка: проверить вручную, что у «בורא פרי העץ» нет записи', e);
      } finally {
        await backToUser1();
      }
    }
  });
});
